// API Health Check
const apis = ['adzuna', 'reed', 'muse', 'rapidapi', 'theirstack', 'coursera'];
const healthResults = [];

for (const api of apis) {
  try {
    // Simple health check - adjust URLs as needed
    const response = await $http.request({
      method: 'GET',
      url: `https://api.${api}.com/health`, // Example URLs
      timeout: 5000
    });

    healthResults.push({
      api: api,
      status: response.status === 200 ? 'healthy' : 'unhealthy',
      responseTime: response.headers['response-time'] || 'unknown'
    });
  } catch (error) {
    healthResults.push({
      api: api,
      status: 'unhealthy',
      error: error.message
    });
  }
}

// Determine if we should proceed with API calls or use backup
const healthyCount = healthResults.filter(r => r.status === 'healthy').length;
const useBackup = healthyCount < 3; // Use backup if less than 3 APIs are healthy

return {
  healthResults,
  healthyCount,
  totalApis: apis.length,
  useBackup,
  timestamp: new Date().toISOString()
};

