// Data Standardization
const jobs = $json.jobs || [];
const standardizedJobs = [];

for (const job of jobs) {
  // Standardize job data format
  const standardized = {
    id: job.id,
    title: job.title?.trim() || 'Unknown Title',
    company: job.company?.trim() || 'Unknown Company',
    location: job.location?.trim() || 'Unknown Location',
    salary_min: typeof job.salary_min === 'number' ? job.salary_min : null,
    salary_max: typeof job.salary_max === 'number' ? job.salary_max : null,
    currency: job.currency || 'USD',
    description: job.description?.trim() || '',
    employment_type: job.employment_type || 'full-time',
    source: job.source,
    posted_date: job.posted_date,
    url: job.url || null,
    remote_allowed: job.location?.toLowerCase().includes('remote') || false,
    standardized_at: new Date().toISOString(),
    isBackup: job.isBackup || false
  };

  // Basic quality checks
  if (standardized.title && standardized.company) {
    standardizedJobs.push(standardized);
  }
}

return {
  standardizedJobs,
  totalStandardized: standardizedJobs.length,
  qualityScore: standardizedJobs.length / jobs.length,
  processedAt: new Date().toISOString()
};

// Quality Validation
const jobs = $json.standardizedJobs || [];
const validationResults = {
  totalJobs: jobs.length,
  validJobs: 0,
  invalidJobs: 0,
  qualityIssues: [],
  qualityScore: 0
};

const validatedJobs = [];

for (const job of jobs) {
  const issues = [];

  // Completeness checks
  if (!job.title || job.title.length < 3) issues.push('Title too short or missing');
  if (!job.company || job.company.length < 2) issues.push('Company missing or invalid');
  if (!job.description || job.description.length < 20) issues.push('Description too short');

  // Accuracy checks
  if (job.salary_min && job.salary_max && job.salary_min > job.salary_max) {
    issues.push('Invalid salary range');
  }

  // Consistency checks
  if (job.location && !job.location.match(/^[a-zA-Z\s,.-]+$/)) {
    issues.push('Invalid location format');
  }

  if (issues.length === 0) {
    validatedJobs.push({
      ...job,
      qualityScore: 1.0,
      validatedAt: new Date().toISOString()
    });
    validationResults.validJobs++;
  } else {
    validationResults.invalidJobs++;
    validationResults.qualityIssues.push({
      jobId: job.id,
      issues: issues
    });
  }
}

validationResults.qualityScore = validationResults.validJobs / validationResults.totalJobs;

return {
  validatedJobs,
  validationResults,
  validationTimestamp: new Date().toISOString()
};

